SELECT FROM story s LEFT JOIN `user` u ON s.author_id = u.user_id WHERE s.status = 2 AND (s.title LIKE CONCAT('%',#{keyword},'%') OR s.intro LIKE CONCAT('%',#{keyword},'%')) AND s.category = #{category}
ORDER BY (s.play_count + 2*s.like_count + 3*s.favorite_count + 4*s.comment_count) DESC ORDER BY s.publish_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM story WHERE status = 2
AND (title LIKE CONCAT('%',#{keyword},'%') OR intro LIKE CONCAT('%',#{keyword},'%'))
AND category = #{category}

